import type { AnydocApi, Format } from './types'

/**
 * Decide which parser to hand a file to.
 *
 * Content wins over the file name: anydoc reads the signature each container
 * specification designates (PDF header, RTF open group, OLE stream names, ZIP
 * package mimetype), so a PDF saved as `.docx` still converts correctly.
 *
 * The extension is only a fallback, and it is a necessary one — plain-text
 * formats carry no signature at all, so `formatFromBytes` returns `undefined`
 * for CSV and it would otherwise be unconvertible.
 */
export function resolveFormat(
  api: AnydocApi,
  bytes: Uint8Array,
  fileName: string,
): Format | undefined {
  return api.formatFromBytes(bytes) ?? api.formatFromPath(fileName)
}

/** Formats routed to the layout-aware engine when the user asks for it. */
export function supportsLayoutEngine(format: Format): boolean {
  return format === 'pdf'
}
