import { supportsLayoutEngine } from '../format'
import type { EngineId, EnginePreference, Format } from '../types'

/**
 * Decide which engine converts a given file.
 *
 * Only PDFs have a choice. Every other format reaches the app through anydoc's
 * parsers, and the layout engine has no reader for them — it starts from
 * positioned glyphs, which only a PDF has.
 */
export function chooseEngine(format: Format, preference: EnginePreference): EngineId {
  if (!supportsLayoutEngine(format)) return 'anydoc'
  return preference === 'fast' ? 'anydoc' : 'odl'
}

/**
 * Should a failed layout-engine conversion be retried with anydoc?
 *
 * Only when the user did not ask for the layout engine by name. Silently
 * substituting an engine someone explicitly chose would hide the fact that it
 * could not read their file.
 */
export function allowsFallback(preference: EnginePreference): boolean {
  return preference !== 'layout'
}
