/// <reference lib="webworker" />
import { loadAnydoc } from '@/core/engines/anydocWasm'
import { loadOdl } from '@/core/engines/odlWasm'
import { convertWithAnydoc, type Outcome } from '@/core/engines/anydoc'
import { convertWithOdl } from '@/core/engines/odl'
import { allowsFallback, chooseEngine } from '@/core/engines/select'
import { resolveFormat } from '@/core/format'
import { toConversionError } from '@/core/errors'
import type { ConvertRequest, ConvertResponse } from '@/core/protocol'
import type { EnginePreference } from '@/core/types'

/**
 * The conversion thread. Both engines run synchronously and single-threaded, so
 * this blocks for the whole document — which is exactly why it is not the UI
 * thread.
 */
self.addEventListener('message', (event: MessageEvent<ConvertRequest>) => {
  const { id, name, bytes, engine } = event.data
  void run(id, name, bytes, engine)
})

async function run(
  id: string,
  name: string,
  bytes: ArrayBuffer,
  preference: EnginePreference,
): Promise<void> {
  let response: ConvertResponse

  try {
    const anydoc = await loadAnydoc()
    const view = new Uint8Array(bytes)

    // anydoc identifies the file for both engines: it is the one that reads
    // magic bytes, and it is loaded either way.
    const format = resolveFormat(anydoc, view, name)
    const engine = format ? chooseEngine(format, preference) : 'anydoc'

    let outcome: Outcome
    if (engine === 'odl' && format) {
      outcome = convertWithOdl(await loadOdl(), view, format)

      // The layout engine is the stricter reader of the two — it needs
      // positioned text, where anydoc will take whatever it can find. Falling
      // back means a PDF it rejects still converts, just without layout
      // analysis. `view` is untouched: wasm-bindgen copies into its own memory.
      if (!outcome.ok && allowsFallback(preference)) {
        const fallback = convertWithAnydoc(anydoc, view, name)
        if (fallback.ok) outcome = fallback
      }
    } else {
      outcome = convertWithAnydoc(anydoc, view, name)
    }

    response = { id, outcome }
  } catch (error) {
    // Reaching here means an engine failed to load — a network or
    // WebAssembly-support problem, not a problem with the user's document.
    response = { id, outcome: { ok: false, error: toConversionError(error) } }
  }

  ;(self as unknown as Worker).postMessage(response)
}
