import type { ConvertErrorCode, Format, OdlApi } from '../types'
import { toConversionError } from '../errors'
import type { Outcome } from './anydoc'

const CODE_PREFIX = /^([a-zA-Z]+): (.*)$/s

/**
 * Rebuild the structured error the Rust side encoded into its message.
 *
 * `JsError` can only carry a string, so `crates/odl-wasm` prefixes the message
 * with the failure code. Restoring the `code` property here means both engines
 * feed the same `toConversionError`, and the UI stays engine-agnostic.
 */
function decode(error: unknown): unknown {
  if (!(error instanceof Error)) return error
  const match = CODE_PREFIX.exec(error.message)
  if (!match) return error
  return Object.assign(new Error(match[2]!), { code: match[1] as ConvertErrorCode })
}

/**
 * Convert a PDF with the layout engine.
 *
 * Like {@link convertWithAnydoc}, the API is injected so the decision logic is
 * testable without instantiating the WASM module. The format is passed in
 * rather than detected: only the caller knows the file was already identified
 * as a PDF, and this engine reads nothing else.
 */
export function convertWithOdl(api: OdlApi, bytes: Uint8Array, format: Format): Outcome {
  const started = performance.now()
  try {
    const markdown = api.pdfToMarkdown(bytes)

    // The engine reports empty pages as an error, so a blank result here means
    // a PDF whose text is all whitespace — unreadable in the same way.
    if (!markdown.trim()) {
      return {
        ok: false,
        error: toConversionError(Object.assign(new Error(''), { code: 'unsupported' }), format),
      }
    }

    return {
      ok: true,
      result: { engine: 'odl', format, markdown, durationMs: performance.now() - started },
    }
  } catch (error) {
    return { ok: false, error: toConversionError(decode(error), format) }
  }
}
