import init, { formatFromBytes, formatFromPath, toMarkdownBytes } from '@firecrawl/anydoc-wasm'
import wasmUrl from '@firecrawl/anydoc-wasm/anydoc_wasm_bg.wasm?url'
import type { AnydocApi } from '../types'

let ready: Promise<AnydocApi> | undefined

/**
 * Instantiate anydoc once per worker.
 *
 * The URL is handed over explicitly rather than left to the glue code's
 * `new URL('anydoc_wasm_bg.wasm', import.meta.url)` default, so the binary is
 * emitted as a content-hashed build asset and resolves correctly under a
 * non-root base path — GitHub Pages serves the app from a subdirectory.
 */
export function loadAnydoc(): Promise<AnydocApi> {
  ready ??= init({ module_or_path: wasmUrl }).then(() => ({
    formatFromBytes,
    formatFromPath,
    toMarkdownBytes,
  }))
  return ready
}
