import type { AnydocApi, ConversionError, ConversionResult } from '../types'
import { resolveFormat } from '../format'
import { toConversionError } from '../errors'

/**
 * Conversions fail routinely — encrypted files, scans, junk uploads — so the
 * outcome is a value rather than an exception. It also crosses a `postMessage`
 * boundary, where a thrown Error would lose its `code`.
 */
export type Outcome = { ok: true; result: ConversionResult } | { ok: false; error: ConversionError }

/**
 * Convert one file with anydoc.
 *
 * Takes the API by injection rather than importing the WASM module, so the
 * decision logic here is unit-testable without instantiating 6.7 MB of binary.
 */
export function convertWithAnydoc(api: AnydocApi, bytes: Uint8Array, fileName: string): Outcome {
  const format = resolveFormat(api, bytes, fileName)
  if (!format) {
    return {
      ok: false,
      error: {
        code: 'unsupported',
        message: 'This file type is not recognised.',
        hint: 'Supported: Word, PowerPoint, Excel, OpenDocument, RTF, EPUB, CSV and PDF.',
      },
    }
  }

  const started = performance.now()
  try {
    // The format is passed explicitly. Re-detection inside the engine would
    // fail for CSV, which carries no signature to detect.
    const markdown = api.toMarkdownBytes(bytes, format)

    // anydoc only throws when it can produce *nothing*; a document that parses
    // but yields no text still comes back empty, and silently showing a blank
    // pane reads as a broken app rather than an unreadable file.
    if (!markdown.trim()) {
      return {
        ok: false,
        error: toConversionError(Object.assign(new Error(''), { code: 'malformed' }), format),
      }
    }

    return {
      ok: true,
      result: { engine: 'anydoc', format, markdown, durationMs: performance.now() - started },
    }
  } catch (error) {
    return { ok: false, error: toConversionError(error, format) }
  }
}
