import init, { pdfToMarkdown } from '@odl/odl_wasm.js'
import wasmUrl from '@odl/odl_wasm_bg.wasm?url'
import type { OdlApi } from '../types'

let ready: Promise<OdlApi> | undefined

/**
 * Instantiate the layout engine once per worker.
 *
 * Loaded lazily and separately from anydoc: it is another 3.4 MB, and a session
 * that never opens a PDF should never pay for it. Same explicit-URL reason as
 * `anydocWasm.ts` — the binary has to survive content hashing and a non-root
 * base path.
 *
 * The package is built by `npm run build:wasm`, which is why `@odl` resolves to
 * a directory outside `src/`. See `vite.config.ts`.
 */
export function loadOdl(): Promise<OdlApi> {
  ready ??= init({ module_or_path: wasmUrl }).then(() => ({ pdfToMarkdown }))
  return ready
}
