import type { ConversionError, ConvertErrorCode, Format } from './types'

const CODES = new Set<ConvertErrorCode>([
  'unsupported',
  'malformed',
  'encrypted',
  'resourceLimit',
  'missingPart',
])

const MESSAGES: Record<ConvertErrorCode, string> = {
  unsupported: 'This file is not in a format that can be converted.',
  malformed: 'The file is damaged, so no readable content could be extracted.',
  encrypted: 'The file is encrypted or password-protected.',
  resourceLimit: 'The file is too large or too deeply nested to convert safely.',
  missingPart: 'The file is incomplete — a part needed to read it is missing.',
}

const HINTS: Partial<Record<ConvertErrorCode, string>> = {
  encrypted: 'Remove the password in the original application, then try again.',
  malformed: 'Try re-saving or re-exporting it from the application that made it.',
  missingPart: 'Re-download or re-export the file — it looks truncated.',
  resourceLimit: 'Try splitting it into smaller files.',
}

/**
 * A PDF that reports `unsupported` is almost always a scan: anydoc extracts
 * embedded text and does no OCR, so a page of pixels yields nothing to convert.
 * Saying that outright is far more useful than "unsupported format".
 */
const IMAGE_ONLY_PDF_HINT =
  'This looks like a scanned or image-only PDF. Its pages are pictures with no ' +
  'embedded text, and this app does no OCR, so there is nothing to extract.'

function readCode(error: unknown): ConvertErrorCode | undefined {
  if (typeof error !== 'object' || error === null) return undefined
  const code = (error as { code?: unknown }).code
  return typeof code === 'string' && CODES.has(code as ConvertErrorCode)
    ? (code as ConvertErrorCode)
    : undefined
}

/** Translate anything thrown by an engine into something worth showing a user. */
export function toConversionError(error: unknown, format?: Format): ConversionError {
  const code = readCode(error)

  if (!code) {
    const raw = error instanceof Error ? error.message : String(error)
    return {
      code: 'unknown',
      message: raw.trim()
        ? `Conversion failed: ${raw}`
        : 'Conversion failed for an unknown reason.',
    }
  }

  const hint = code === 'unsupported' && format === 'pdf' ? IMAGE_ONLY_PDF_HINT : HINTS[code]

  return hint ? { code, message: MESSAGES[code], hint } : { code, message: MESSAGES[code] }
}
